variables.$fxv#10:
// YUMA-AIA-D05  New AI app consent (user or admin), first seen in the tenant
// Type: Sentinel scheduled analytics rule (every 1h, look back 1h, baseline 30d). Triggers playbook PB2 (register).
// Table: AuditLogs. Licence: any Entra ID tier.
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/auditlogs
// Maps: ISM-2137 (no user consent to agents), ISM-2138 (review consents), ISM-2139 (log consent),
//   ISM-2134/2135 (register) | E8 restrict administrative privileges
//   ATT&CK T1528 | ATLAS AML.T0012 | OWASP ASI03, ASI04, LLM03
// Field paths match Microsoft's CredentialAddedAfterAdminConsent and SuspiciousOAuthApp_OfflineAccess rules.
// Approved apps (watchlist YumaAIRegisterApproved, maintained by PB2) are suppressed unless consent is by a user.
// Note: Defender for Cloud Apps app governance (OAuthAppInfo) gives richer data if licensed; see README.
let lookback = 1h;
let baseline = 30d;
let AIKeywords = dynamic(["openai", "chatgpt", "anthropic", "claude", "copilot", "gemini", "perplexity",
    "deepseek", "mistral", "grok", "otter", "fireflies", "read.ai", "n8n", "zapier", "langchain",
    "cursor", "notion ai", "jasper", "writer", "poe", "character.ai", "huggingface"]);
let Consents = AuditLogs
    | where TimeGenerated > ago(baseline)
    | where LoggedByService =~ "Core Directory" and Category =~ "ApplicationManagement"
    | where OperationName =~ "Consent to application" and Result =~ "success"
    | mv-apply TargetResource = TargetResources on (
          where tostring(TargetResource.type) =~ "ServicePrincipal"
          | extend AppSpId = tostring(TargetResource.id),
                   AppName = tostring(TargetResource.displayName),
                   AppAgentType = tostring(TargetResource.agentType),
                   Props = TargetResource.modifiedProperties
          | take 1)
    | mv-apply Prop = Props on (
          summarize Bag = make_bag(bag_pack(tostring(Prop.displayName), trim(@'[\"\s]+', tostring(Prop.newValue))), 100));
let Approved = _GetWatchlist("YumaAIRegisterApproved") | project SearchKey;
let PreviouslySeen = Consents
    | where TimeGenerated <= ago(lookback)
    | distinct AppSpId;
Consents
| where TimeGenerated > ago(lookback)
| extend IsAdminConsent = tostring(Bag["ConsentContext.IsAdminConsent"]),
         ConsentAction = tostring(Bag["ConsentAction.Permissions"])
| parse ConsentAction with * "ConsentType: " ConsentType ", Scope: " Scopes "," *
| extend IsAgentic = isnotempty(AppAgentType) and AppAgentType !~ "notAgentic",
         IsAINamed = AppName has_any (AIKeywords) or AppName matches regex @"(?i)\b(ai|gpt|llm|mcp|agent|copilot)\b",
         IsFirstSeen = AppSpId !in (PreviouslySeen),
         IsUserConsent = IsAdminConsent =~ "False"
| where IsAgentic or IsAINamed
| where IsFirstSeen or IsUserConsent
| where AppSpId !in (Approved) or IsUserConsent
| extend ConsentedByUpn = tostring(InitiatedBy.user.userPrincipalName),
         ConsentedByIp = tostring(InitiatedBy.user.ipAddress)
| extend Severity = iff(IsUserConsent, "Medium", "Low"),
         RegisterAction = "Create or update ISM-2135 register entry; schedule ISM-2138 review in 6 months"
| project TimeGenerated, AppName, AppSpId, AppAgentType, IsAgentic, IsAINamed, IsFirstSeen, IsUserConsent,
          ConsentType, Scopes, ConsentedByUpn, ConsentedByIp, Severity, RegisterAction, CorrelationId

variables.$fxv#11:
// YUMA-AIA-D07  Agent identity or AI service principal signs in from a new IP/ASN, to a new resource,
//               with a new credential type, or with a burst of failures (14-day baseline)
// Type: Sentinel scheduled analytics rule (every 1h, look back 14d). Feeds playbook PB1.
// Table: AADServicePrincipalSignInLogs (column Agent = "Details of agentic sign-in").
// Licence: Entra ID P1 or P2 to ingest sign-in logs.
//   https://learn.microsoft.com/en-us/azure/sentinel/connect-azure-active-directory
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/aadserviceprincipalsigninlogs
//   https://learn.microsoft.com/en-us/entra/agent-id/sign-in-audit-logs-agents
// Agent is a string column holding JSON; agentType / parentAppId keys follow the Graph agentSignIn resource
//   (https://learn.microsoft.com/en-us/graph/api/resources/agentic-agentsignin?view=graph-rest-beta). UNVALIDATED
//   against live data: confirm key casing in a tenant with Entra Agent ID before enabling.
// Fallback: tenants without Agent ID data are covered by the AI name match.
// Maps: ISM-2133, ISM-2136, ISM-2141, ISM-2142, ISM-2148 (response via PB1) | E8 restrict administrative privileges
//   ATT&CK T1078.004, T1550.001 | ATLAS AML.T0012, AML.T0055 | OWASP ASI03, ASI10
let lookback = 14d;
let recent = 1h;
let FailureThreshold = 20;
let AIKeywords = dynamic(["openai", "chatgpt", "anthropic", "claude", "copilot", "gemini", "perplexity",
    "deepseek", "mistral", "grok", "n8n", "zapier", "langchain", "agent", "mcp"]);
let AgentSignIns = AADServicePrincipalSignInLogs
    | where TimeGenerated > ago(lookback)
    | extend AgentInfo = parse_json(Agent)
    | extend AgentType = tostring(AgentInfo.agentType),
             ParentAppId = tostring(AgentInfo.parentAppId)
    | extend IsAgentic = isnotempty(AgentType) and AgentType !~ "notAgentic"
    | where IsAgentic or ServicePrincipalName has_any (AIKeywords)
    | extend Succeeded = ResultType == "0" or ResultType =~ "Success";
let Baseline = AgentSignIns
    | where TimeGenerated <= ago(recent) and Succeeded
    | summarize KnownIPs = make_set(IPAddress, 1000),
                KnownASNs = make_set(AutonomousSystemNumber, 500),
                KnownResources = make_set(ResourceDisplayName, 500),
                KnownCredTypes = make_set(ClientCredentialType, 20),
                BaselineSignIns = count()
             by ServicePrincipalId;
AgentSignIns
| where TimeGenerated > ago(recent)
| summarize FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
            SuccessCount = countif(Succeeded), FailureCount = countif(not(Succeeded)),
            FailureCodes = make_set_if(ResultType, not(Succeeded), 20)
         by ServicePrincipalId, ServicePrincipalName, AppId, AgentType, ParentAppId, IsAgentic,
            IPAddress, AutonomousSystemNumber, ResourceDisplayName, ClientCredentialType
| join kind=leftouter Baseline on ServicePrincipalId
| extend HasBaseline = isnotnull(BaselineSignIns)
| extend NewIP = HasBaseline and SuccessCount > 0 and not(set_has_element(KnownIPs, IPAddress)),
         NewASN = HasBaseline and SuccessCount > 0 and not(set_has_element(KnownASNs, AutonomousSystemNumber)),
         NewResource = HasBaseline and SuccessCount > 0 and not(set_has_element(KnownResources, ResourceDisplayName)),
         NewCredentialType = HasBaseline and SuccessCount > 0 and not(set_has_element(KnownCredTypes, ClientCredentialType)),
         FailureBurst = FailureCount >= FailureThreshold,
         UsesSecret = ClientCredentialType has "secret"   // ISM-2141/2142 prefer managed or certificate credentials
| where NewASN or NewResource or NewCredentialType or FailureBurst or (NewIP and UsesSecret)
| extend Reasons = strcat_array(pack_array(
             iff(NewIP, "new IP", ""), iff(NewASN, "new ASN", ""), iff(NewResource, "new resource", ""),
             iff(NewCredentialType, "new credential type", ""), iff(FailureBurst, "failure burst", ""),
             iff(UsesSecret, "static secret", "")), "; ")
| extend Severity = case((NewASN and NewResource) or FailureBurst, "High", IsAgentic, "Medium", "Low")
| project FirstSeen, LastSeen, ServicePrincipalName, ServicePrincipalId, AppId, AgentType, ParentAppId, IsAgentic,
          IPAddress, AutonomousSystemNumber, ResourceDisplayName, ClientCredentialType, SuccessCount, FailureCount,
          FailureCodes, Reasons, Severity

variables.$fxv#12:
// YUMA-AIA-D08  Agent or AI app Microsoft Graph data-access burst (mail, files, sites, chats, users, MCP for Enterprise)
// Type: Sentinel scheduled analytics rule (every 1h, look back 14d). Feeds playbook PB1.
// Table: MicrosoftGraphActivityLogs. Licence: Entra ID P1 or P2 plus a diagnostic setting; volume can be large.
//   https://learn.microsoft.com/en-us/graph/microsoft-graph-activity-logs-overview
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/microsoftgraphactivitylogs
// Requests to the Microsoft MCP Server for Enterprise have "/enterprise" in RequestUri (per the overview page).
// Agent scoping: service principals seen with an agentic sign-in (AADServicePrincipalSignInLogs.Agent) or an AI name.
// Maps: ISM-2157 (lesser of user and task scope), ISM-2159 (log tool invocations) | E8 restrict administrative privileges
//   ATT&CK T1114.002, T1530, T1087.004 | ATLAS AML.T0085.001, AML.T0086, AML.T0036 | OWASP LLM06, LLM02, ASI02, ASI10
let lookback = 14d;
let recent = 1h;
let MinRequests = 200;        // floor so tiny apps do not alert on noise
let SigmaThreshold = 3.0;
let AIKeywords = dynamic(["openai", "chatgpt", "anthropic", "claude", "copilot", "gemini", "perplexity",
    "deepseek", "mistral", "grok", "n8n", "zapier", "langchain", "agent", "mcp"]);
let AgentApps = AADServicePrincipalSignInLogs
    | where TimeGenerated > ago(lookback)
    | extend AgentType = tostring(parse_json(Agent).agentType)
    | where (isnotempty(AgentType) and AgentType !~ "notAgentic") or ServicePrincipalName has_any (AIKeywords)
    | summarize AppName = take_any(ServicePrincipalName), AgentType = take_any(AgentType) by AppId;
let SensitiveCalls = MicrosoftGraphActivityLogs
    | where TimeGenerated > ago(lookback)
    | where AppId in ((AgentApps | project AppId))
    | extend Path = tolower(tostring(split(RequestUri, "?")[0]))
    | extend Category = case(Path has "/enterprise", "MCPEnterprise",
                             Path has "/messages" or Path has "/mailfolders", "Mail",
                             Path has "/drive" or Path has "/drives", "Files",
                             Path has "/sites", "Sites",
                             Path has "/chats" or Path has "/channels", "Chat",
                             Path has "/users" or Path has "/groups", "Directory",
                             "Other")
    | where Category != "Other"
    | extend TargetUser = extract(@"/users/([^/]+)/", 1, Path);
let Baseline = SensitiveCalls
    | where TimeGenerated <= ago(recent)
    | summarize Hourly = count() by AppId, bin(TimeGenerated, 1h)
    | summarize AvgHourly = avg(Hourly), StdHourly = stdev(Hourly), BaselineHours = count() by AppId;
SensitiveCalls
| where TimeGenerated > ago(recent)
| summarize Requests = count(),
            BytesOut = sum(ResponseSizeBytes),
            DistinctTargetUsers = dcount(TargetUser),
            Categories = make_set(Category, 10),
            Methods = make_set(RequestMethod, 10),
            IPs = make_set(IPAddress, 20),
            SampleUris = make_set(RequestUri, 10),
            FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated)
         by AppId, ServicePrincipalId
| join kind=inner AgentApps on AppId
| join kind=leftouter Baseline on AppId
| extend Threshold = iff(isnull(AvgHourly), real(MinRequests), max_of(real(MinRequests), AvgHourly + SigmaThreshold * coalesce(StdHourly, 0.0)))
| where Requests > Threshold
| extend Severity = iff(Categories has_any ("Mail", "Files", "MCPEnterprise") and DistinctTargetUsers > 5, "High", "Medium")
| project FirstSeen, LastSeen, AppName, AppId, ServicePrincipalId, AgentType, Requests, Threshold, AvgHourly, StdHourly,
          BytesOut, DistinctTargetUsers, Categories, Methods, IPs, SampleUris, Severity

variables.$fxv#13:
// YUMA-AIA-D10  Prompt-injection or jailbreak signal followed by exfiltration-like activity by the same user within 2h
// Type: Sentinel scheduled analytics rule (every 1h, look back 3h) or Defender XDR custom detection.
// Purpose: Microsoft already detects or blocks the injection itself (Defender for Endpoint "Suspicious AI prompt
//   injection", Copilot Studio real-time protection, Copilot jailbreak rule). This rule does not re-detect injection;
//   it correlates the alert with what the user or agent did next.
//   https://learn.microsoft.com/en-us/defender-endpoint/ai-agent-runtime-protection-overview
//   https://learn.microsoft.com/en-us/defender-xdr/security-for-ai/ai-agent-real-time-protection
// Tables: AlertInfo, AlertEvidence (Defender XDR), CopilotActivity (Microsoft Copilot connector), CloudAppEvents
//   (Defender for Cloud Apps with the Microsoft 365 app connector).
//   https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-alertinfo-table
//   https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-alertevidence-table
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/copilotactivity
//   https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-cloudappevents-table
// UNVALIDATED: alert titles for the Copilot Studio protection; whether CopilotActivity.ActorUserId is the Entra object
//   ID; RawEventData.UserId as UPN; the exfil ActionType list (standard Microsoft 365 audit operation names).
// Maps: ISM-2158 (retrieved content untrusted), ISM-1924, ISM-2113 | E8 n/a (detective)
//   ATT&CK T1567, T1530, T1114 | ATLAS AML.T0051.001, AML.T0054, AML.T0086 | OWASP LLM01, LLM02, ASI01, ASI02
let lookback = 3h;
let window = 2h;
let MinExfilEvents = 10;
let ExfilActions = dynamic(["FileDownloaded", "FileSyncDownloadedFull", "FileCopied", "AnonymousLinkCreated",
    "AnonymousLinkUsed", "CompanyLinkCreated", "SharingSet", "SharingInvitationCreated", "AddedToSecureLink",
    "Send", "SendAs", "New-InboxRule", "Set-InboxRule", "UpdateInboxRules", "MailItemsAccessed"]);
let InjectionTitles = dynamic(["prompt injection", "jailbreak", "XPIA", "UPIA"]);
let DefenderTriggers = AlertInfo
    | where Timestamp > ago(lookback)
    | where Title has_any (InjectionTitles)
    | join kind=inner (
        AlertEvidence
        | where Timestamp > ago(lookback)
        | where EntityType =~ "User"
        | project AlertId, AccountObjectId, AccountUpn
      ) on AlertId
    | project TriggerTime = Timestamp, TriggerSource = strcat("Defender: ", Title), TriggerId = AlertId,
              AccountObjectId, AccountUpn;
let CopilotTriggers = CopilotActivity
    | where TimeGenerated > ago(lookback)
    | where RecordType == "CopilotInteraction" and tostring(LLMEventData) has "JailbreakDetected"
    | project TriggerTime = TimeGenerated, TriggerSource = strcat("CopilotActivity jailbreak: ", AppHost),
              TriggerId = RecordId, AccountObjectId = ActorUserId, AccountUpn = ActorName;
let Triggers = union isfuzzy=true DefenderTriggers, CopilotTriggers
    | extend Keys = pack_array(tolower(AccountObjectId), tolower(AccountUpn))
    | mv-expand Key = Keys to typeof(string)
    | where isnotempty(Key);
let Activity = CloudAppEvents
    | where Timestamp > ago(lookback)
    | where ActionType in (ExfilActions)
    | extend Keys = pack_array(tolower(AccountObjectId), tolower(tostring(RawEventData.UserId)))
    | mv-expand Key = Keys to typeof(string)
    | where isnotempty(Key)
    | project ActivityTime = Timestamp, Key, ActionType, Application, ObjectName, IPAddress, ReportId,
              ActivityAccountObjectId = AccountObjectId, ActivityAccountName = AccountDisplayName;
Triggers
| join kind=inner Activity on Key
| where ActivityTime between (TriggerTime .. (TriggerTime + window))
| summarize ExfilEvents = dcount(ReportId),
            Actions = make_set(ActionType, 20),
            Apps = make_set(Application, 10),
            SampleObjects = make_set(ObjectName, 20),
            IPs = make_set(IPAddress, 10),
            FirstActivity = min(ActivityTime), LastActivity = max(ActivityTime)
         by TriggerId, TriggerSource, TriggerTime, AccountUpn, AccountObjectId = ActivityAccountObjectId
| where ExfilEvents >= MinExfilEvents or Actions has_any ("AnonymousLinkCreated", "New-InboxRule", "Set-InboxRule")
| extend Severity = iff(Actions has_any ("AnonymousLinkCreated", "New-InboxRule", "Set-InboxRule"), "High", "Medium")
| project TriggerTime, TriggerSource, TriggerId, AccountUpn, AccountObjectId, ExfilEvents, Actions, Apps,
          SampleObjects, IPs, FirstActivity, LastActivity, Severity

variables.$fxv#14:
// YUMA-AIA-D14  AI-speed exploitation or scanning burst against an internet-facing app (Application Gateway WAF)
// Type: Sentinel scheduled analytics rule (every 10m, look back 1h). Triggers playbook PB3 (enrich and block).
// Tables: AGWFirewallLogs, AGWAccessLogs (resource-specific App Gateway diagnostics), ThreatIntelIndicators (optional).
// Licence: Azure Application Gateway WAF_v2 with diagnostic settings in resource-specific mode; Sentinel TI for the join.
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/agwfirewalllogs
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/agwaccesslogs
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/threatintelindicators
// Logic: one client IP tripping many distinct WAF rules across many distinct URIs inside 10 minutes is typical of
//   automated (often LLM-driven) exploit tooling. User agent is enrichment, not the trigger, because it is spoofable.
// Maps: ISM-2116 (CTI for detection) | E8 patch applications
//   ATT&CK T1190, T1595.002 | ATLAS AML.T0049, AML.T0006 | OWASP ASI05 (where an agent is the attacker), LLM10
let lookback = 1h;
let binSize = 10m;
let MinDistinctRules = 8;
let MinDistinctUris = 15;
let MinHits = 40;
let AIAgentUA = dynamic(["GPTBot", "ChatGPT-User", "OAI-SearchBot", "ClaudeBot", "Claude-User", "Claude-SearchBot",
    "PerplexityBot", "Perplexity-User", "Meta-ExternalAgent", "Bytespider", "CCBot", "Google-Extended"]);
let AutomationUA = dynamic(["python-requests", "aiohttp", "httpx", "Go-http-client", "curl/", "Wget", "node-fetch",
    "axios", "HeadlessChrome", "Playwright", "puppeteer", "nuclei", "sqlmap"]);
let Bursts = AGWFirewallLogs
    | where TimeGenerated > ago(lookback)
    | where Action in ("Matched", "Blocked", "Detected")
    | summarize Hits = count(), DistinctRules = dcount(RuleId), DistinctUris = dcount(RequestUri),
                Rules = make_set(RuleId, 50), Messages = make_set(Message, 20), SampleUris = make_set(RequestUri, 20),
                Hosts = make_set(Hostname, 5), Actions = make_set(Action, 3)
             by ClientIp, Window = bin(TimeGenerated, binSize)
    | where DistinctRules >= MinDistinctRules and DistinctUris >= MinDistinctUris and Hits >= MinHits;
let UAContext = AGWAccessLogs
    | where TimeGenerated > ago(lookback)
    | where ClientIp in ((Bursts | project ClientIp))
    | summarize UserAgents = make_set(UserAgent, 10), Requests = count(),
                Status4xx = countif(HttpStatus between (400 .. 499)), Status5xx = countif(HttpStatus >= 500),
                Status2xx = countif(HttpStatus between (200 .. 299))
             by ClientIp;
let TI = ThreatIntelIndicators
    | where TimeGenerated > ago(14d) and IsActive == true
    | where ObservableKey has "ipv4-addr" or ObservableKey has "ipv6-addr"
    | summarize TIConfidence = max(Confidence) by ClientIp = ObservableValue;
Bursts
| join kind=leftouter UAContext on ClientIp
| join kind=leftouter TI on ClientIp
| extend UAText = tostring(UserAgents)
| extend ClaimsAIAgent = UAText has_any (AIAgentUA),
         AutomationClient = UAText has_any (AutomationUA),
         Got2xxDuringBurst = coalesce(Status2xx, 0) > 0 and Actions has "Matched"
| extend Severity = case(Got2xxDuringBurst or coalesce(TIConfidence, 0) >= 70, "High",
                         "Medium")
| project Window, ClientIp, Hits, DistinctRules, DistinctUris, Rules, Messages, SampleUris, Hosts, Actions, UserAgents,
          ClaimsAIAgent, AutomationClient, Requests, Status2xx, Status4xx, Status5xx, TIConfidence, Severity

variables.$fxv#15:
// YUMA-AIA-D01  (DRAFT HUNT) Shadow AI: non-browser processes talking to AI model APIs (local agents, CLIs, scripts)
// Table: DeviceNetworkEvents. Licence: Defender for Endpoint P2 (or Defender XDR / Microsoft 365 E5 Security).
//   https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-devicenetworkevents-table
// Maps: ISM-2074 (AI usage policy), ISM-2095, ISM-2134 (register) | E8 application control
//   ATT&CK T1567 | ATLAS AML.T0112.000, AML.T0096, AML.T0040 | OWASP ASI04, LLM03
// Tuning: add the customer's approved tools to ApprovedProcesses. Keep AIApiDomains in sync with the customer's AI usage policy (ISM-2074).
let lookback = 7d;
let AIApiDomains = dynamic(["api.openai.com", "chatgpt.com", "api.anthropic.com", "claude.ai",
    "generativelanguage.googleapis.com", "aiplatform.googleapis.com", "api.mistral.ai", "api.deepseek.com",
    "api.x.ai", "api.perplexity.ai", "api.groq.com", "api.together.xyz", "openrouter.ai", "api.cohere.com",
    "huggingface.co", "api-inference.huggingface.co", "api.moonshot.cn", "dashscope.aliyuncs.com"]);
let Browsers = dynamic(["msedge.exe", "chrome.exe", "firefox.exe", "brave.exe", "opera.exe", "safari", "iexplore.exe",
    "msedgewebview2.exe"]);
let ApprovedProcesses = dynamic([]);
DeviceNetworkEvents
| where Timestamp > ago(lookback)
| where ActionType in ("ConnectionSuccess", "HttpConnectionInspected", "SslConnectionInspected")
| where isnotempty(RemoteUrl) and RemoteUrl has_any (AIApiDomains)
| where InitiatingProcessFileName !in~ (Browsers) and InitiatingProcessFileName !in~ (ApprovedProcesses)
| summarize Connections = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp),
            Destinations = make_set(RemoteUrl, 20), SampleCommandLines = make_set(InitiatingProcessCommandLine, 5),
            Parents = make_set(InitiatingProcessParentFileName, 5)
         by DeviceName, DeviceId, InitiatingProcessFileName, InitiatingProcessAccountUpn
| order by Connections desc

variables.$fxv#16:
// YUMA-AIA-D06  (DRAFT HUNT) Agent identities and AI service principals authenticating with static client secrets
// Table: AADServicePrincipalSignInLogs. Licence: Entra ID P1/P2 for sign-in log ingestion.
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/aadserviceprincipalsigninlogs
// ClientCredentialType values (clientSecret, clientAssertion, federatedIdentityCredential, managedIdentity, certificate)
//   are from the Graph signIn resource; confirm the exact strings in the tenant. UNVALIDATED.
// Maps: ISM-2141, ISM-2142, ISM-2146 | E8 restrict administrative privileges
//   ATT&CK T1552.001 | ATLAS AML.T0055, AML.T0083 | OWASP ASI03
let lookback = 30d;
let AIKeywords = dynamic(["openai", "chatgpt", "anthropic", "claude", "copilot", "gemini", "perplexity", "mistral",
    "deepseek", "grok", "n8n", "zapier", "langchain", "agent", "mcp"]);
AADServicePrincipalSignInLogs
| where TimeGenerated > ago(lookback)
| extend AgentType = tostring(parse_json(Agent).agentType)
| where (isnotempty(AgentType) and AgentType !~ "notAgentic") or ServicePrincipalName has_any (AIKeywords)
| where ClientCredentialType has "secret"
| summarize SignIns = count(), Resources = make_set(ResourceDisplayName, 20), IPs = make_set(IPAddress, 20),
            CredentialKeyIds = make_set(ServicePrincipalCredentialKeyId, 10), LastSeen = max(TimeGenerated)
         by ServicePrincipalName, ServicePrincipalId, AppId, AgentType, ClientCredentialType
| order by SignIns desc

variables.$fxv#17:
// YUMA-AIA-D09  (DRAFT HUNT) AI agent register review in Defender XDR with ISM-2133/2135 gap flags.
// The same AgentsInfo data is synced daily into the Sentinel register table AIAgentRegister_CL by PB4
//   (functions/PB4-AgentsInfoRegisterSync.kql); use the YumaAIRegister() function in Sentinel.
// Table: AgentsInfo (preview; replaces the deprecated AIAgentsInfo). Defender XDR advanced hunting.
//   https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-agentsinfo-table
// Licence: per the AgentsInfo page (Defender XDR with AI agent inventory); confirm before selling.
// Maps: ISM-2133 (unique identity), ISM-2134/2135 (register and fields), ISM-2156 (least-privilege tools)
//   ATLAS AML.T0084 | OWASP ASI04, ASI10
AgentsInfo
| summarize arg_max(Timestamp, *) by AgentId
| where LifecycleStatus !~ "Deleted"
| extend OwnerCount = array_length(Owners),
         ToolCount = array_length(DeclaredTools),
         McpServerCount = array_length(McpServers),
         DataSourceCount = array_length(DeclaredDataSources)
| extend Gap_NoOwner = coalesce(OwnerCount, 0) == 0,
         Gap_NoPurpose = isempty(AgentDescription),
         Gap_NoEntraIdentity = isempty(EntraAgentId),                       // ISM-2133
         Gap_NoInstructions = isempty(Instructions),
         Flag_SharedWide = tostring(SharedWith) has_any ("Organization", "Everyone", "Tenant"),   // value set UNVALIDATED
         Flag_HasMcp = coalesce(McpServerCount, 0) > 0
| project AgentId, AgentName, Platform, PublishedStatus, LifecycleStatus, Availability, AgentDescription, Owners,
          EntraAgentId, EntraBlueprintId, Model, ToolsAuthenticationType, Permissions, DeclaredTools, McpServers,
          DeclaredDataSources, SharedWith, InstanceCount, CreatedDateTime, LastPublishedDateTime, LastUpdatedDateTime,
          Gap_NoOwner, Gap_NoPurpose, Gap_NoEntraIdentity, Gap_NoInstructions, Flag_SharedWide, Flag_HasMcp
| order by Gap_NoOwner desc, Gap_NoEntraIdentity desc, Flag_HasMcp desc

variables.$fxv#18:
// YUMA-AIA-D13  (DRAFT HUNT) AI crawler or agent user agents enumerating an app, or probing MCP / AI endpoints
// Table: AGWAccessLogs. Licence: Application Gateway diagnostics (resource-specific mode).
//   https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/agwaccesslogs
// User agents are self-declared and spoofable; verify against vendor-published IP ranges (planned watchlist).
// Maps: ISM-2116 | ATT&CK T1595.002, T1593 | ATLAS AML.T0006, AML.T0093 | OWASP LLM10
let lookback = 1d;
let AIAgentUA = dynamic(["GPTBot", "ChatGPT-User", "OAI-SearchBot", "ClaudeBot", "Claude-User", "Claude-SearchBot",
    "PerplexityBot", "Perplexity-User", "Meta-ExternalAgent", "Bytespider", "CCBot", "Google-Extended"]);
let ProbePaths = dynamic(["/mcp", "/sse", "/.well-known/mcp", "/v1/chat/completions", "/v1/completions",
    "/api/generate", "/.well-known/ai-plugin.json", "/openapi.json", "/llms.txt"]);
AGWAccessLogs
| where TimeGenerated > ago(lookback)
| extend ClaimsAIAgent = UserAgent has_any (AIAgentUA),
         IsProbe = tolower(RequestUri) has_any (ProbePaths)
| where ClaimsAIAgent or IsProbe
| summarize Requests = count(), DistinctUris = dcount(RequestUri), NotFound = countif(HttpStatus == 404),
            ProbeHits = countif(IsProbe), UserAgents = make_set(UserAgent, 10), SampleUris = make_set(RequestUri, 20),
            Hosts = make_set(Host, 5), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated)
         by ClientIp, ClaimsAIAgent
| extend NotFoundRatio = round(todouble(NotFound) / Requests, 2)
| where ProbeHits > 0 or DistinctUris > 200 or NotFoundRatio > 0.5
| order by ProbeHits desc, DistinctUris desc

